// back to the lane, whose offloader's OnDone sees it on the loop's thread.
type LoopWorker interface {
	// Work runs job, sent by the lane whose index is lane.
	Work(lane int, job LoopJobValue)
}

// LoopOutbound is one lane's queue to its worker (R3), preallocated
// (LoopValue.Outbound). Send is called on the lane's thread only, with the
// lane's LoopIO, and never blocks: it queues the job and wakes the worker, or
// refuses with LoopOutboundFull, queueing nothing.
